package org.jlinalg.genetics;

import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.Test;
import static org.jlinalg.genetics.FumaChromatinMapping.*;
import static org.jlinalg.genetics.FumaVariantGeneMapping.*;

class FumaChromatinMappingTest {
    private static final Filter NONE=new Filter(0,Double.NaN,List.of(),States.ANY,7,List.of(),Binary.ANY);
    private static final List<Gene> GENES=List.of(new Gene("G1","ONE",1,100,200,"+","protein_coding"),new Gene("G2","TWO",1,250,350,"-","lncRNA"));
    private static Variant v(String id,int position,double p){return new Variant(id,"rs"+id,1,position,p,0,5,"1",List.of("rsLead"+id));}
    private static final List<Variant> VARIANTS=List.of(v("1",100,1e-10),v("2",200,.01),v("3",250,Double.NaN));
    private static final List<Annotation> ANNOTATIONS=List.of(new Annotation("1",10,2,Map.of("brain",7.0),Map.of("enh",1.0)),new Annotation("2",5,1,Map.of("brain",8.0),Map.of("enh",0.0)),new Annotation("3",20,3,Map.of("brain",Double.NaN),Map.of("enh",1.0)));
    private static Interaction i(String id,String region,String genes,String rs,String tissue){return new Interaction(id,new Region(region),new Region("1:250-350"),genes.isEmpty()?List.of():List.of(genes.split(":")),rs.isEmpty()?List.of():List.of(rs.split(";")),tissue);}
    private static Inputs in(List<Interaction> interactions,Membership membership){return new Inputs(interactions,NONE,null,false,List.of(),membership,Coordinates.SOURCE_CLOSED,1000);}
    private static Options options(int budget){return new Options("synthetic-GRCh37",Set.of(),Mhc.KEEP,null,null,false,null,null,NONE,false,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN),budget);}
    private static FumaVariantGeneMapping.Result run(Inputs input){return FumaVariantGeneMapping.map(GENES,VARIANTS,ANNOTATIONS,List.of(),List.of(),options(1000),input);}
    private static FumaVariantGeneMapping.Result simple(List<Interaction> interactions){return run(in(interactions,Membership.SOURCE_GLOBAL));}
    @Test void closedEndpointsAndActualLinksAreRetained(){var r=simple(List.of(i("I1","1:100-200","G2","rs1;rs2","Brain cortex")));assertEquals(List.of("1","2"),r.chromatin().evidence().stream().map(Evidence::uid).toList());assertEquals(1,r.genes().size());assertEquals(1e-10,r.genes().get(0).minGwasP());assertEquals(List.of("rsLead1","rsLead2"),r.genes().get(0).independentRsIds());assertEquals(List.of("Brain cortex"),r.chromatin().genes().get(0).tissues());}
    @Test void bedConversionChangesOnlyLowerBoundaryMembership(){var row=i("I1","1:100-200","G2","rs1;rs2","A");var r=run(new Inputs(List.of(row),NONE,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.BED,100));assertEquals(List.of("2"),r.chromatin().evidence().stream().map(Evidence::uid).toList());assertEquals(.01,r.genes().get(0).minGwasP());}
    @Test void zeroStartClosedRegionsAndZeroOnlyPointDoNotInventCandidateZero(){assertEquals(1,simple(List.of(i("I1","1:0-100","G2","rs1","A"))).chromatin().evidence().size());assertTrue(simple(List.of(i("I1","1:0-0","G2","rs1","A"))).genes().isEmpty());}
    @Test void globalPoolCanMapAListedSnpFromAnotherRow(){var rows=List.of(i("I1","1:100-100","G2","rs3","A"),i("I2","1:250-250","G1","rs1","B"));var r=simple(rows);assertEquals(2,r.chromatin().evidence().size());assertTrue(r.chromatin().evidence().stream().noneMatch(Evidence::listedInInteraction));assertTrue(r.warnings().stream().anyMatch(w->w.startsWith("CROSS-ROW")));assertTrue(run(in(rows,Membership.PER_INTERACTION)).chromatin().evidence().isEmpty());}
    @Test void perInteractionAllowsOnlyItsOwnListedOverlaps(){var rows=List.of(i("I1","1:100-250","G2","rs1","A"),i("I2","1:250-250","G1","rs3","B"));var r=run(in(rows,Membership.PER_INTERACTION));assertEquals(List.of("1","3"),r.chromatin().evidence().stream().map(Evidence::uid).toList());assertTrue(r.chromatin().evidence().stream().allMatch(Evidence::listedInInteraction));}
    @Test void finalPoolRestrictionRetainsDeclarationWithoutFabricatingGwasEvidence(){var rows=List.of(i("I1","1:100-100","G2","rs3","A"),new Interaction("I2",new Region("1:250-250"),new Region("1:100-200"),List.of("G1"),List.of("rs1"),"B"));var input=new Inputs(rows,NONE,null,true,List.of(new Promoter(new Region("1:250-350"),List.of("G2"))),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);var r=run(input);assertEquals(1,r.genes().size());assertTrue(Double.isNaN(r.genes().get(0).minGwasP()));assertTrue(r.genes().get(0).independentRsIds().isEmpty());assertTrue(r.chromatin().evidence().isEmpty());assertEquals("retained-without-final-overlap",r.chromatin().interactions().get(0).status());assertTrue(r.warnings().stream().anyMatch(w->w.startsWith("RETAINED WITHOUT FINAL SUPPORT")));}
    @Test void sourceFlagsSurviveRejectionOfEveryPromoterRow(){var rows=List.of(i("I1","1:100-200","G2","rs1;rs2","A"));var input=new Inputs(rows,NONE,null,true,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);var r=run(input);assertTrue(r.genes().isEmpty());assertEquals(2,r.chromatin().candidates().stream().filter(CandidateDisposition::retainedPoolFlag).count());assertTrue(r.chromatin().candidates().stream().noneMatch(CandidateDisposition::mapped));}
    @Test void perInteractionHasNoRetainedPoolAfterAllRowsAreRejected(){var input=new Inputs(List.of(i("I1","1:100-200","G2","rs1;rs2","A")),NONE,null,true,List.of(),Membership.PER_INTERACTION,Coordinates.SOURCE_CLOSED,100);assertTrue(run(input).chromatin().candidates().stream().noneMatch(CandidateDisposition::retainedPoolFlag));}
    @Test void missingGeneListRejectsInteractionButSourcePoolFlagRemains(){var r=simple(List.of(i("I1","1:100-200","","rs1;rs2","A")));assertTrue(r.genes().isEmpty());assertEquals("excluded-no-gene-list",r.chromatin().interactions().get(0).status());assertEquals(2,r.chromatin().candidates().stream().filter(CandidateDisposition::retainedPoolFlag).count());}
    @Test void unknownGeneHasRetainedRowAndNoEligibleLink(){var r=simple(List.of(i("I1","1:100-200","UNKNOWN","rs1;rs2","A")));assertTrue(r.genes().isEmpty());assertTrue(r.chromatin().evidence().isEmpty());assertEquals("retained-no-eligible-gene",r.chromatin().interactions().get(0).status());}
    @Test void biotypeFilterRestrictsEligibleGenesWithoutErasingRawInteraction(){var options=new Options("fixture",Set.of("protein_coding"),Mhc.KEEP,null,null,false,null,null,NONE,false,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN),100);var r=FumaVariantGeneMapping.map(GENES,VARIANTS,ANNOTATIONS,List.of(),List.of(),options,in(List.of(i("I1","1:100-200","G2","rs1;rs2","A")),Membership.SOURCE_GLOBAL));assertTrue(r.genes().isEmpty());assertEquals(List.of("G2"),r.chromatin().interactions().get(0).effectiveGenes());assertTrue(r.chromatin().interactions().get(0).eligibleGenes().isEmpty());}
    @Test void promoterKeysAreExactStringsIncludingLeadingZeros(){var input=new Inputs(List.of(new Interaction("I1",new Region("1:100-200"),new Region("01:250-350"),List.of("G2"),List.of("rs1"),"A")),NONE,null,true,List.of(new Promoter(new Region("1:250-350"),List.of("G1"))),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);assertEquals("excluded-no-exact-promoter-key",run(input).chromatin().interactions().get(0).status());}
    @Test void promoterLookupReplacesOriginalGenesAndUnionsRepeatedKeys(){var input=new Inputs(List.of(i("I1","1:100-200","UNKNOWN","rs1","A")),NONE,null,true,List.of(new Promoter(new Region("1:250-350"),List.of("G1")),new Promoter(new Region("1:250-350"),List.of("G2","G1"))),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);var r=run(input);assertEquals(List.of("G1","G2"),r.chromatin().interactions().get(0).effectiveGenes());assertEquals(2,r.chromatin().evidence().size());assertEquals(2,r.genes().size());}
    @Test void enhancerFilterIsAppliedByUid(){var input=new Inputs(List.of(i("I1","1:100-200","G2","rs1;rs2","A")),NONE,Set.of("2"),false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);assertEquals(List.of("2"),run(input).chromatin().evidence().stream().map(Evidence::uid).toList());}
    @Test void chromatinCaddComesFromAnnotationAndIncludesEquality(){var filter=new Filter(10,Double.NaN,List.of(),States.ANY,7,List.of(),Binary.ANY);var input=new Inputs(List.of(i("I1","1:100-250","G2","rs1;rs2;rs3","A")),filter,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);assertEquals(List.of("1","3"),run(input).chromatin().evidence().stream().map(Evidence::uid).toList());}
    @Test void chromatinRdbComesFromAnnotationAndIncludesEquality(){var filter=new Filter(0,2,List.of(),States.ANY,7,List.of(),Binary.ANY);var input=new Inputs(List.of(i("I1","1:100-250","G2","rs1;rs2;rs3","A")),filter,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);assertEquals(List.of("1","2"),run(input).chromatin().evidence().stream().map(Evidence::uid).toList());}
    @Test void sharedStateRulesApplyToInteractionCandidates(){var filter=new Filter(0,Double.NaN,List.of("brain"),States.MODE,7,List.of(),Binary.ANY);var input=new Inputs(List.of(i("I1","1:100-250","G2","rs1;rs2;rs3","A")),filter,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);assertEquals(List.of("1"),run(input).chromatin().evidence().stream().map(Evidence::uid).toList());}
    @Test void singleBinaryTrackIsAnExplicitNativeCorrection(){var filter=new Filter(0,Double.NaN,List.of(),States.ANY,7,List.of("enh"),Binary.ANY);var input=new Inputs(List.of(i("I1","1:100-250","G2","rs1;rs2;rs3","A")),filter,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100);assertEquals(List.of("1","3"),run(input).chromatin().evidence().stream().map(Evidence::uid).toList());}
    @Test void duplicateRowsRetainProvenanceButGeneVariantCountsAreUnique(){var r=simple(List.of(i("I1","1:100-200","G2","rs1;rs2","A"),i("I2","1:100-200","G2","rs1;rs2","A")));assertEquals(4,r.chromatin().evidence().size());assertEquals(2,r.chromatin().genes().get(0).variantUids().size());assertEquals(4,r.chromatin().genes().get(0).evidenceRows());assertEquals(List.of("A"),r.chromatin().genes().get(0).tissues());}
    @Test void multipleTissuesAreRetainedEvenForSameVariant(){var r=simple(List.of(i("I1","1:100-100","G2","rs1","Brain cortex"),i("I2","1:100-100","G2","rs1","Adult heart")));assertEquals(List.of("Brain cortex","Adult heart"),r.chromatin().genes().get(0).tissues());assertEquals(1,r.chromatin().genes().get(0).variantUids().size());}
    @Test void unlistedCandidatesInsideOneRegionDoNotEnterGlobalPool(){var r=simple(List.of(i("I1","1:100-250","G2","rs1","A")));assertEquals(List.of("1"),r.chromatin().evidence().stream().map(Evidence::uid).toList());}
    @Test void unknownListedRsidsAreNotSynthesized(){var r=simple(List.of(i("I1","1:100-200","G2","rsMissing","A")));assertTrue(r.genes().isEmpty());assertTrue(r.chromatin().evidence().isEmpty());assertTrue(r.warnings().stream().anyMatch(w->w.startsWith("UNAVAILABLE LISTED SNPs")));}
    @Test void intervalAndGeneAreNotRequiredToShareChromosome(){var genes=List.of(new Gene("G2","TWO",2,1,2,"+","protein_coding"));var r=FumaVariantGeneMapping.map(genes,VARIANTS,ANNOTATIONS,List.of(),List.of(),options(100),in(List.of(i("I1","1:100-100","G2","rs1","A")),Membership.SOURCE_GLOBAL));assertEquals(1,r.genes().size());assertEquals(2,r.genes().get(0).gene().chromosome());}
    @Test void duplicateInteractionIdsFailBeforeMapping(){var row=i("I1","1:100-200","G2","rs1","A");assertThrows(IllegalArgumentException.class,()->in(List.of(row,row),Membership.SOURCE_GLOBAL));}
    @Test void malformedRegionsAndNonhumanChromosomesAreExplicitlyRejected(){for(String region:List.of("chr1:1-2","X:1-2","1:-1-2","1:3-2","24:1-2","1:1.5-2"))assertThrows(IllegalArgumentException.class,()->new Region(region));}
    @Test void bedZeroWidthRegionsFailInsteadOfBecomingPointHits(){var row=i("I1","1:100-100","G2","rs1","A");assertThrows(IllegalArgumentException.class,()->new Inputs(List.of(row),NONE,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.BED,100));}
    @Test void missingSelectedAnnotationColumnFailsEvenWithEmptyInteractions(){var filter=new Filter(0,Double.NaN,List.of("missing"),States.ANY,7,List.of(),Binary.ANY);assertThrows(IllegalArgumentException.class,()->run(new Inputs(List.of(),filter,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,100)));}
    @Test void storedOverlapBudgetIsEnforcedBeforeLargeHitLists(){var input=new Inputs(List.of(i("I1","1:100-250","G2","rs1;rs2;rs3","A")),NONE,null,false,List.of(),Membership.SOURCE_GLOBAL,Coordinates.SOURCE_CLOSED,1);assertThrows(IllegalArgumentException.class,()->run(input));}
    @Test void combinedEvidenceBudgetAlsoBoundsChromatinGeneExpansion(){var input=in(List.of(i("I1","1:100-200","G1:G2","rs1;rs2","A")),Membership.SOURCE_GLOBAL);assertThrows(IllegalArgumentException.class,()->FumaVariantGeneMapping.map(GENES,VARIANTS,ANNOTATIONS,List.of(),List.of(),options(1),input));}
    @Test void emptyChromatinInputIsAnEnabledEmptyAnalysis(){var r=simple(List.of());assertTrue(r.genes().isEmpty());assertEquals(3,r.chromatin().candidates().size());assertTrue(r.chromatin().candidates().stream().noneMatch(CandidateDisposition::retainedPoolFlag));}
    @Test void noModulesStillFailsWithTheOriginalMapSignature(){assertThrows(IllegalArgumentException.class,()->FumaVariantGeneMapping.map(GENES,VARIANTS,ANNOTATIONS,List.of(),List.of(),options(100)));}
    @Test void combinedSummaryUnionsActualEvidenceAcrossAllThreeMethods(){var opts=new Options("fixture",Set.of(),Mhc.KEEP,null,null,true,0,null,NONE,true,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN),100);var eq=List.of(new Eqtl("2","G2","GTEx","Brain",.01,.1,"+"));var r=FumaVariantGeneMapping.map(GENES,VARIANTS,ANNOTATIONS,List.of(),eq,opts,in(List.of(i("I1","1:100-100","G2","rs1","A")),Membership.SOURCE_GLOBAL));var g=r.genes().stream().filter(x->x.gene().id().equals("G2")).findFirst().orElseThrow();assertEquals(1,g.positionalVariants());assertEquals(1,g.eqtlVariants());assertEquals(1e-10,g.minGwasP());assertEquals(Set.of("rsLead1","rsLead2","rsLead3"),Set.copyOf(g.independentRsIds()));}
}
